window.NOTE_DEMOS={"y2026q16":{"kind":"explore","title":"安全三属性受到了什么伤害","task":"点击事件，观察主要破坏机密性、完整性还是可用性。","initial":"同一事件可能影响多项，但考试通常抓最直接后果。","actions":[{"label":"服务器过载无法访问","stage":"可用性受损","result":"授权用户在需要时无法获得服务。","tone":"good"},{"label":"成绩被陌生人读取","stage":"机密性受损","result":"信息被未授权主体获知。","tone":"good"},{"label":"成绩被偷偷改动","stage":"完整性受损","result":"数据被未授权篡改。","tone":"good"}]},"y2025q30":{"kind":"explore","title":"把安全措施放到正确防线","task":"点击技术，观察它主要保护身份、机密性、检测还是完整性。","initial":"一套系统需要多层安全措施。","actions":[{"label":"人脸识别","stage":"身份认证","result":"用生物特征核验主体。","tone":"good"},{"label":"加密","stage":"机密性保护","result":"未授权者难以理解密文。","tone":"good"},{"label":"入侵检测","stage":"监测与告警","result":"发现可疑流量或行为。","tone":"good"},{"label":"数字签名","stage":"来源与完整性验证","result":"验证签名者和内容是否被篡改。","tone":"good"}]},"y2024q49":{"kind":"explore","title":"守住一台遭遇洪泛的文件服务器","task":"点击流量与防护模块，区分攻击、检测和缓解。","initial":"正常请求100次/秒，异常流量突然升到20万次/秒。","actions":[{"label":"大量请求耗尽资源","stage":"DoS/DDoS","result":"主要破坏服务可用性。","tone":"bad"},{"label":"IDS发出异常告警","stage":"检测系统","result":"IDS是防护组件，不是攻击名称。","tone":"good"},{"label":"限速与流量清洗","stage":"缓解措施","result":"过滤异常来源并保护后端容量。","tone":"good"},{"label":"服务器离线就一定被攻击","stage":"证据不足","result":"故障和突发合法流量也会造成不可用。","tone":"warn"}]},"y2023q39":{"kind":"sequence","title":"让校外电脑通过VPN进入校园内网","task":"完成认证、建隧道、访问内网资源和断开四个真实状态。","steps":[{"label":"连接VPN网关并认证","detail":"网关验证账户、证书或多因素凭据。"},{"label":"协商密钥并建立隧道","detail":"公网中的报文被封装和加密。"},{"label":"访问授权的内网资源","detail":"逻辑上像接入组织网络，但仍受访问控制。"},{"label":"断开VPN","detail":"隧道和临时路由撤销，公网本身没有变成私有线路。"}]},"y2020q28":{"kind":"explore","title":"先看病毒怎样破坏，再搭多层防线","task":"点击攻击表现和防护措施，观察“特征”与“对策”的对应关系。","initial":"病毒可以潜伏后再触发，任何单一防护都不够。","actions":[{"label":"删除文件并拖慢系统","stage":"破坏性","result":"危害数据完整性和系统可用性。","tone":"bad"},{"label":"不打开陌生附件","stage":"减少入口","result":"先阻断常见钓鱼和恶意附件。","tone":"good"},{"label":"及时安装补丁","stage":"修复漏洞","result":"应从可信渠道更新。","tone":"good"},{"label":"最小权限＋多因素认证","stage":"限制后果","result":"降低账户被盗和恶意程序提权风险。","tone":"good"},{"label":"只安装杀毒软件","stage":"防线不完整","result":"仍需要备份、防火墙、补丁和谨慎操作。","tone":"bad"}]},"y2020q20":{"kind":"choose","title":"先问“有没有授权”","task":"点击网络行为，观察权限、目的和影响三个判断维度。","options":[{"label":"给自己的设备安装安全更新","result":"有权限且降低风险，属于正当防护。","tone":"good"},{"label":"未经同意查看同学账号","result":"没有授权，即使没有修改内容也不合规。","tone":"bad"},{"label":"为好玩让网站无法访问","result":"破坏服务可用性，目的不能使行为正当。","tone":"bad"},{"label":"批量发送垃圾信息","result":"消耗资源并干扰他人，不符合网络伦理。","tone":"bad"}]},"y2026q30":{"kind":"explore","title":"发布AI内容前过三道门","task":"点击检查项，形成公开传播前的操作顺序。","initial":"AI输出已经生成，但还不能直接发布。","actions":[{"label":"核验事实","stage":"与可靠来源交叉检查","result":"生成内容可能包含虚构或过时信息。","tone":"good"},{"label":"检查权利","stage":"确认隐私、著作权与授权边界","result":"能生成不代表有权传播。","tone":"good"},{"label":"按场景标识","stage":"说明AI生成合成属性","result":"公开传播时遵守现行标识规则和平台要求。","tone":"good"},{"label":"直接发布恶搞内容","stage":"可能误导并侵害他人","result":"娱乐目的不能免除真实性和权利责任。","tone":"bad"}]}};
window.NOTE_NAVIGATION={"y2026q16":{"related":[{"id":"y2024q49","label":"DoS/DDoS通过耗尽资源破坏可用性","reason":"DoS/DDoS是破坏可用性的具体方式，但普通故障和合法流量过载也可能造成同一后果。","chapter":8},{"id":"y2022q39","label":"网络拓扑和分区会影响攻击扩散与可用性","reason":"网络冗余、检测和切换机制针对单点故障风险，可把可用性目标落实为连接与设备设计。","chapter":8}],"topics":[]},"y2025q30":{"related":[{"id":"merged-15","label":"加密、解密、公钥与私钥","reason":"详细区分加密保护内容、签名验证来源与完整性、摘要检测变化，避免把所有密码技术都叫加密。","chapter":8},{"id":"y2026q16","label":"过载与宕机会破坏信息系统可用性","reason":"先明确机密性、完整性和可用性，再判断题目中的安全技术主要满足哪一个目标。","chapter":8},{"id":"y2020q28","label":"病毒具有破坏性，安全仍需多层措施","reason":"多种安全技术须与补丁、备份、最小权限和用户判断配合，才能覆盖恶意软件带来的不同后果。","chapter":8}],"topics":[]},"merged-15":{"related":[{"id":"y2023q16","label":"HTTPS为HTTP通信增加加密与身份认证","reason":"HTTPS把传输加密与站点身份认证结合起来，是公钥可信绑定和会话保护的应用实例。","chapter":6},{"id":"y2025q30","label":"生物识别、加密、入侵检测和数字签名都可保障安全","reason":"把加密、签名与身份识别、入侵检测并排比较，可按机密性、完整性和检测目标选择技术。","chapter":8},{"id":"merged-17","label":"区块链结构、共识、可追溯性与信任边界","reason":"区块链同时使用哈希和签名，但难以篡改、验证签署者与隐藏内容仍是不同能力。","chapter":9}],"topics":[{"id":"cmp-security-goals","title":"安全：加密、摘要、签名、证书与防火墙"}]},"y2021q18":{"related":[{"id":"y2023q16","label":"HTTPS为HTTP通信增加加密与身份认证","reason":"理解HTTPS实际保护的传输与证书范围，才能解释为什么带锁图标的仿冒站仍需警惕。","chapter":6},{"id":"y2026q14","label":"URL由协议、主机和资源路径等部分组成","reason":"拆出真正的主机部分，防止被路径中的机构名、相似拼写或子域名误导。","chapter":6},{"id":"y2020q28","label":"病毒具有破坏性，安全仍需多层措施","reason":"链接和附件核实是多层防护的一环，还需配合更新、安全软件、独立备份和账户保护。","chapter":8}],"topics":[{"id":"cmp-security-goals","title":"安全：加密、摘要、签名、证书与防火墙"}]},"y2024q49":{"related":[{"id":"y2026q16","label":"过载与宕机会破坏信息系统可用性","reason":"拒绝服务的直接后果是授权用户无法使用服务，因而主要破坏可用性。","chapter":8},{"id":"merged-16","label":"防火墙与网络访问控制","reason":"访问控制可参与缓解攻击，但防火墙只控制经过检查路径的流量，不能单独保证服务一直可用。","chapter":8}],"topics":[]},"y2022q39":{"related":[{"id":"merged-16","label":"防火墙与网络访问控制","reason":"网络分区只有配合明确的方向、地址和端口规则，才能把信任边界落实为访问控制。","chapter":8},{"id":"y2026q16","label":"过载与宕机会破坏信息系统可用性","reason":"关键链路或设备成为单点故障时主要影响可用性，可据此辨认拓扑设计的安全目标。","chapter":8}],"topics":[]},"y2023q39":{"related":[{"id":"merged-15","label":"加密、解密、公钥与私钥","reason":"VPN依赖加密与认证，应继续区分共享密钥、公私钥和身份绑定所解决的问题。","chapter":8},{"id":"merged-16","label":"防火墙与网络访问控制","reason":"终端通过VPN接入后仍需受访问规则约束，受保护的连接不等于获得组织内全部资源权限。","chapter":8}],"topics":[]},"y2020q28":{"related":[{"id":"y2021q18","label":"熟人转发和HTTPS都不能替你确认链接真实","reason":"可疑消息的独立核实是具体防护步骤，熟人转发和HTTPS都不能取代对链接与动作的判断。","chapter":8},{"id":"merged-16","label":"防火墙与网络访问控制","reason":"允许通过防火墙的连接仍可能携带恶意内容，网络访问控制与恶意软件防护必须配合。","chapter":8},{"id":"merged-4","label":"文件名、扩展名、关联、只读与权限要分层判断","reason":"扩展名参与类型识别却不保证内容安全，改名或隐藏后缀也不会把内部格式或恶意行为变掉。","chapter":2}],"topics":[]},"merged-16":{"related":[{"id":"y2022q39","label":"网络拓扑和分区会影响攻击扩散与可用性","reason":"网络分区划定信任边界，防火墙规则决定跨区流量如何放行，两者共同限制攻击传播范围。","chapter":8},{"id":"y2021q15","label":"网卡连接本机与网络，路由器负责跨网转发","reason":"有网卡、默认网关和路由只说明接入及转发路径，请求是否获准还要代入访问规则。","chapter":6},{"id":"y2020q28","label":"病毒具有破坏性，安全仍需多层措施","reason":"防火墙不能覆盖被允许连接中的全部恶意内容，也不能替代补丁、安全软件和备份。","chapter":8}],"topics":[{"id":"cmp-security-goals","title":"安全：加密、摘要、签名、证书与防火墙"}]},"syllabus-windows-security":{"related":[{"id":"y2025q26","label":"账户与管理员权限","reason":"第2章解释账户类型与操作入口；这里从安全目标理解UAC。","chapter":2},{"id":"merged-4","label":"文件权限、属性与EFS","reason":"需要实施文件访问保护时回到原设置入口和版本条件。","chapter":2},{"id":"y2026q33","label":"系统还原与个人文件备份","reason":"分别核对系统状态回退和文档恢复，不把隔离当作还原。","chapter":2}],"topics":[]},"y2020q20":{"related":[{"id":"y2026q30","label":"使用AI生成内容要核验、披露并尊重权利","reason":"AI参与创作与传播时同样要核验内容、说明来源并判断披露义务，生成方式不会消除权利边界。","chapter":8},{"id":"y2025q37","label":"全文检索既能检索题录也可能获取全文","reason":"数据库全文能否获取由收录与权限决定，取得文件之后的引用和传播仍需另外判断授权。","chapter":6}],"topics":[]},"y2026q30":{"related":[{"id":"y2025q20","label":"生成式人工智能能辅助多种任务，但输出必须核验","reason":"生成式模型可能输出错误事实或伪造出处，这是人工核验和说明AI参与程度的直接原因。","chapter":9},{"id":"y2020q20","label":"网络行为要尊重权限、署名与责任边界","reason":"将AI内容的披露要求与通常的访问权限、署名和传播责任结合，避免把标识当作全部授权。","chapter":8},{"id":"y2024q17","label":"信息检索从需求分析到结果评价形成闭环","reason":"核验模型输出需要明确问题、查找合适资源并评价来源，不能只重复询问同一个生成结果。","chapter":6}],"topics":[]}};
window.NOTE_SEARCH_ENTRIES=[{"id":"y2026q16","kind":"note","chapter":8,"chapterTitle":"信息安全","title":"过载与宕机会破坏信息系统可用性","aliases":["CIA","保密性","完整性","安全风险","漏洞"],"fields":[{"anchor":"y2026q16--conclusion","title":"核心结论","text":"系统无法在需要时为授权用户提供服务，主要破坏可用性。"},{"anchor":"y2026q16--point-0","title":"保密性：谁能看到","aliases":["保密性：谁能看到","先认识保护对象与安全目标"],"text":"机密性防止未授权泄露：成绩未被修改，但被无权查看的人读取，主要是机密性受损。"},{"anchor":"y2026q16--point-1","title":"完整性：是否被擅自改变","aliases":["完整性：是否被擅自改变","先认识保护对象与安全目标"],"text":"完整性防止未经授权的篡改或破坏：有人把成绩65改为95，即使系统仍可登录，完整性也已受损。"},{"anchor":"y2026q16--point-2","title":"可用性：需要时能否使用","aliases":["可用性：需要时能否使用","先认识保护对象与安全目标"],"text":"可用性要求授权用户在需要时能及时访问系统和信息：成绩数据仍在，但查询系统过载打不开，主要是可用性受损。"},{"anchor":"y2026q16--point-3","title":"保护对象与CIA三项目标","aliases":["保护对象与CIA三项目标","先认识保护对象与安全目标"],"text":"信息安全保护信息及处理它的系统，关注存储、处理和传输全过程。先确认受保护的对象与授权用户，再看保密性（也称机密性）、完整性、可用性；安全措施不只包括加密，还包括权限、维护、备份和管理。"},{"anchor":"y2026q16--point-4","title":"威胁、漏洞、攻击与风险","aliases":["威胁、漏洞、攻击与风险","分清风险与已经发生的后果"],"text":"威胁是可能造成损害的因素，漏洞是可能被利用的弱点，攻击是试图破坏安全的行为，风险要结合发生可能性与后果判断。有漏洞不等于已被攻击；发现异常也需核实原因，不能把所有故障都认作攻击。"},{"anchor":"y2026q16--point-5","title":"相同结果可能有不同原因","aliases":["相同结果可能有不同原因","分清风险与已经发生的后果"],"text":"例：未修补的软件缺陷是漏洞，利用它窃取资料的行为是攻击，资料泄露主要损害保密性；停电造成服务中断主要影响可用性。前者可通过补丁、权限和监测降低风险，后者还需供电和恢复措施，不能只用一个安全产品解决。"},{"anchor":"y2026q16--boundary","title":"易错边界","text":"一次事件可能同时影响多种属性，答题时应抓住题干直接后果。"},{"anchor":"y2026q16--sources","title":"来源与核验记录","text":"题目以系统过载或崩溃考查信息安全基本属性。 2026 第16题 NIST：机密性定义 NIST：完整性定义 NIST：可用性定义 NIST：威胁、漏洞与风险（风险定义入口） NIST：漏洞 NIST：威胁"},{"anchor":"y2026q16--demo","title":"安全三属性受到了什么伤害","text":"点击事件，观察主要破坏机密性、完整性还是可用性。"}]},{"id":"y2025q30","kind":"note","chapter":8,"chapterTitle":"信息安全","title":"生物识别、加密、入侵检测和数字签名都可保障安全","aliases":["身份认证","授权","访问控制","多因素认证","IDS","IPS","自主可控","国产安全产品"],"fields":[{"anchor":"y2025q30--conclusion","title":"核心结论","text":"身份识别、机密性保护、攻击检测和完整性认证分别由不同安全技术承担，应形成纵深防御。"},{"anchor":"y2025q30--point-0","title":"从身份到资源权限","aliases":["从身份到资源权限"],"text":"人脸识别属于生物特征身份认证。"},{"anchor":"y2025q30--point-1","title":"按安全目标选择措施","aliases":["按安全目标选择措施"],"text":"加密保护数据机密性。"},{"anchor":"y2025q30--point-2","title":"按安全目标选择措施","aliases":["按安全目标选择措施"],"text":"入侵检测发现可疑行为，数字签名验证来源与完整性。"},{"anchor":"y2025q30--point-3","title":"认证、授权与访问控制","aliases":["认证、授权与访问控制","从身份到资源权限"],"text":"认证先核验“你是谁”，授权再确定“你可以做什么”，访问控制在具体请求发生时执行策略。例如学生登录成功可以查看自己的成绩，仍无权修改成绩；密码正确不等于具有全部权限。"},{"anchor":"y2025q30--point-4","title":"多因素不是多输一次密码","aliases":["多因素不是多输一次密码","从身份到资源权限"],"text":"密码属于“知道什么”，持有的认证器属于“拥有什么”，指纹等属于“是什么”。多因素认证组合不同类别的因素；密码再加另一个密码仍是同类因素。生物识别也可能误判，模板与备用验证方式同样需要保护。"},{"anchor":"y2025q30--point-5","title":"IDS、IPS、反病毒与防火墙","aliases":["IDS、IPS、反病毒与防火墙","按安全目标选择措施"],"text":"IDS主要监测、分析并告警；IPS还可按策略阻止检测到的活动。反恶意软件工具检查和处置可疑程序/文件，防火墙控制网络访问。一个产品可以集成多项功能，但不能由“装了其中一种”推出所有威胁都已消除。"},{"anchor":"y2025q30--point-6","title":"自主可控关注哪些条件","aliases":["自主可控关注哪些条件","自主可控与国产安全产品"],"text":"自主可控关注关键技术、产品和供应链能否被掌握、维护和持续保障。理解时可检查数据会否被非法控制、供应或支持中断会否影响业务、组件是否适配及能否及时修补；不能把“国产”直接等同于没有漏洞，也不等于必须与外界断开。"},{"anchor":"y2025q30--point-7","title":"国产安全产品的特点与应用","aliases":["国产安全产品的特点与应用","自主可控与国产安全产品"],"text":"国产安全产品仍应按任务理解：终端安全软件可把病毒查杀、补丁管理和设备管控集中管理；网络防火墙面向边界流量，安全审计记录和分析行为。例如奇安信天擎的厂商说明列有统一下发策略、终端查杀及管控，用于多终端集中防护；这是功能实例，不是唯一产品或效果保证。"},{"anchor":"y2025q30--point-8","title":"选型后仍需配置和维护","aliases":["选型后仍需配置和维护","自主可控与国产安全产品"],"text":"选用安全产品先确定被保护对象和威胁，再核对系统/硬件适配、所需功能、更新与服务条件；涉及适用目录的产品，还应核对官方认证/检测信息中的型号、版本与有效范围。产品名称、国产标签和认证记录都不能代替正确配置与持续维护。"},{"anchor":"y2025q30--boundary","title":"易错边界","text":"单一技术不能覆盖所有安全目标；生物特征也需要模板保护和备用认证机制。"},{"anchor":"y2025q30--sources","title":"来源与核验记录","text":"题目要求选择用于保障信息安全的技术。 2025 第30题 NIST：认证身份 NIST：授权与权限 NIST：多因素认证 NIST：IDS NIST：IPS 2026山东专升本官方考纲：信息安全与社会责任第五项 网信办：网络安全审查办法，供应连续性及安全可控因素 奇安信：天擎终端安全系统功能示例（厂商说明，非效果保证） 网信办：网络关键设备和网络安全专用产品认证/检测查询"},{"anchor":"y2025q30--demo","title":"把安全措施放到正确防线","text":"点击技术，观察它主要保护身份、机密性、检测还是完整性。"}]},{"id":"merged-15","kind":"note","chapter":8,"chapterTitle":"信息安全","title":"加密、解密、公钥与私钥","aliases":[],"fields":[{"anchor":"merged-15--conclusion","title":"核心结论","text":"加密用于保密，数字签名用于核验签署来源与数据完整性，摘要用于检测数据是否改变。三者目标不同；使用公钥前还必须确认它确实属于预期对象。"},{"anchor":"merged-15--point-0","title":"对称与非对称的分工","aliases":["对称与非对称的分工","明文、密钥与两类加密"],"text":"对称加密由双方共享密钥，适合大量数据处理；非对称机制使用相关联的公钥与私钥，常用于身份认证、密钥建立或数字签名。"},{"anchor":"merged-15--point-1","title":"保密消息使用接收者的密钥","aliases":["保密消息使用接收者的密钥","明文、密钥与两类加密"],"text":"使用支持加密的公钥算法时，甲给乙发保密消息：甲用乙的公钥加密，乙用自己的私钥解密。要让谁读，就使用谁的加密公钥；私钥保密，公钥可公开但须确认归属。"},{"anchor":"merged-15--point-2","title":"签名者私钥与验证公钥","aliases":["签名者私钥与验证公钥","摘要和签名解决不同问题"],"text":"甲要证明消息由自己签署：用甲的私钥生成签名，乙用甲的公钥验证。验证时同时需要收到的消息和签名；改动消息再配原签名，正常情况下验签失败。签名不是把“公钥加密”简单反过来用。"},{"anchor":"merged-15--point-3","title":"摘要不能解密或独立认证来源","aliases":["摘要不能解密或独立认证来源","摘要和签名解决不同问题"],"text":"摘要通常不需要密钥，也没有对应的解密操作。收到消息后可重算摘要与可信原摘要比较；若攻击者能同时替换消息和摘要，二者一致仍不能证明消息来自谁。"},{"anchor":"merged-15--point-4","title":"摘要和签名解决不同问题","aliases":["摘要和签名解决不同问题"],"text":"数字签名可支持来源认证、完整性和不可否认性证据，但不自动隐藏内容，也不证明签署内容在现实世界中为真。"},{"anchor":"merged-15--point-5","title":"使用公钥前确认身份绑定","aliases":["使用公钥前确认身份绑定"],"text":"数字证书等机制可把身份与公钥建立可信绑定；若公钥本身被冒名替换，验签通过也不能据此确认预期身份。并非每种非对称算法都同时支持加密和签名。"},{"anchor":"merged-15--point-6","title":"明文、密钥与两类加密","aliases":["明文、密钥与两类加密"],"text":"非对称机制通常比对称加密慢，实际系统常用非对称机制建立或保护会话密钥，再用对称加密处理大量正文。"},{"anchor":"merged-15--point-7","title":"明文、密钥与两类加密","aliases":["明文、密钥与两类加密"],"text":"采用合适算法、安全参数并正确实现时，从公开密钥推导私钥在计算上应不可行；这不是数学上绝对不可能，也不保证薄弱参数或错误实现仍安全。"},{"anchor":"merged-15--point-8","title":"摘要和签名解决不同问题","aliases":["摘要和签名解决不同问题"],"text":"安全算法、参数与实现且私钥未泄露时，仅持公钥的接收方难以伪造签署者的有效签名。数字签名是按密码算法对消息生成的验证数据，不是手写签名照片；把照片加密传输也不等同于数字签名。"},{"anchor":"merged-15--point-9","title":"明文、密文与共享密钥流程","aliases":["明文、密文与共享密钥流程","明文、密钥与两类加密"],"text":"明文是待保护的原始内容，密文是加密后的表示，解密是在合适密钥与算法下恢复明文。对称方案中，双方先安全获得共享秘密，发送方加密、接收方解密；若把明文密钥与密文一起交给未授权者，不能据此保密。算法公开与密钥保密是两回事。"},{"anchor":"merged-15--point-10","title":"摘要碰撞与算法边界","aliases":["摘要碰撞与算法边界","摘要和签名解决不同问题"],"text":"摘要把任意长度输入映射为定长结果；不同消息可能出现相同摘要，所以不能称为数学上唯一编号。MD5、SHA-1已有碰撞安全问题，不宜用于要求抗碰撞的现代安全签名等场景；不能因它们仍能计算就称为强安全算法。本页演示采用SHA-256。"},{"anchor":"merged-15--point-11","title":"证书验证的对象和条件","aliases":["证书验证的对象和条件","使用公钥前确认身份绑定"],"text":"证书通常包含主体、公钥、有效期等信息，并由签发者签名。使用证书时还需检查可信签发链、有效性与用途/目标匹配等条件；证书不是私钥，不是消息密文，也不能代替对业务内容真实性的核验。"},{"anchor":"merged-15--point-12","title":"从摘要到签名和验证","aliases":["从摘要到签名和验证","摘要和签名解决不同问题"],"text":"实际签名通常把消息摘要纳入签名者私钥参与的算法计算，验证方用收到的消息、签名和相应公钥检验关系。签名数据与可读原文可以同时传递；若还要保密，应另用适当加密机制，不能把摘要或签名当作整份正文的密文。"},{"anchor":"merged-15--boundary","title":"易错边界","text":"验签成功表示签名与该消息、该公钥相匹配；是否可信还取决于公钥身份绑定和私钥管理。编码可逆不等于加密，普通摘要不等于签名。"},{"anchor":"merged-15--comparison","title":"知识点对照","text":" 操作 使用什么 主要回答什么 摘要 消息；通常无密钥 数据与已知摘要是否一致 对称加密 / 解密 双方共享的密钥 没有密钥者能否读取内容 公钥加密 / 私钥解密 接收者的公钥 / 私钥 让接收者恢复保密内容 私钥签名 / 公钥验签 签署者的私钥 / 公钥 签名是否匹配此消息与此公钥 证书验证 身份、公钥、签发者及信任关系 此公钥能否可信地关联到该身份"},{"anchor":"merged-15--sources","title":"来源与核验记录","text":"真题从基本过程、非对称密钥分工、推导难度和效率考查密码技术。 2020 第39题 2023 第29题 2025 第43题 2026 第44题 2022 第50题 2021 第30题 NIST FIPS 186-5：Digital Signature Standard NIST：Public Key Certificate 术语 MDN：SubtleCrypto.sign MDN：SubtleCrypto.encrypt MDN：SubtleCrypto.digest Microsoft：公钥与私钥 IETF RFC5280：证书字段及路径验证 IETF RFC6151：MD5的抗碰撞边界 NIST：SHA-1与现代摘要算法适用边界"},{"anchor":"merged-15--demo","title":"亲自签名、篡改和验签，再比较加密与摘要","text":"本卡调用浏览器密码API计算；修改原文、换公钥或改密文，结果会真实变化。"}]},{"id":"y2021q18","kind":"note","chapter":8,"chapterTitle":"信息安全","title":"熟人转发和HTTPS都不能替你确认链接真实","aliases":[],"fields":[{"anchor":"y2021q18--conclusion","title":"核心结论","text":"打开消息中的链接前，应核对完整域名、来源和要求执行的动作；熟人账户也可能被盗用。"},{"anchor":"y2021q18--point-0","title":"域名与路径不能混看","aliases":["域名与路径不能混看","先辨诱导与真实站点"],"text":"仿冒站可借相似拼写、子域名和看似官方的路径混淆身份。"},{"anchor":"y2021q18--point-1","title":"先辨诱导与真实站点","aliases":["先辨诱导与真实站点"],"text":"HTTPS保护连接传输，不保证网站运营者诚实，更不能证明消息本身真实。"},{"anchor":"y2021q18--point-2","title":"用独立渠道核实","aliases":["用独立渠道核实","独立核实并保护凭据"],"text":"涉及账号、支付和验证码时，主动从已知官方入口进入，并通过独立渠道核实。"},{"anchor":"y2021q18--point-3","title":"独立核实并保护凭据","aliases":["独立核实并保护凭据"],"text":"不要在演示或陌生表单中输入真实账号密码、身份证号和验证码。"},{"anchor":"y2021q18--point-4","title":"社会工程不一定依赖恶意附件","aliases":["社会工程不一定依赖恶意附件","先辨诱导与真实站点"],"text":"社会工程利用信任、恐惧或紧迫感诱导人采取不当动作，钓鱼是常见形式。核实要换用独立渠道，而不是继续拨打可疑消息自带号码；没有下载附件也可能因交出验证码或授权而受损。"},{"anchor":"y2021q18--boundary","title":"易错边界","text":"“好友发来”“有锁标志”“页面长得像”都不足以建立信任；官方来源也要看准确地址与发布主体。"},{"anchor":"y2021q18--sources","title":"来源与核验记录","text":"围绕钓鱼链接的识别、应用与易错边界整理。 2021 第18题 "},{"anchor":"y2021q18--demo","title":"看清地址，再决定从哪里进入","text":"展开消息地址，核对站点身份；没有真实登录或密码输入。"}]},{"id":"y2024q49","kind":"note","chapter":8,"chapterTitle":"信息安全","title":"DoS/DDoS通过耗尽资源破坏可用性","aliases":[],"fields":[{"anchor":"y2024q49--conclusion","title":"核心结论","text":"大量请求耗尽资源、使合法用户无法获得服务，属于拒绝服务攻击（DoS）；只有明确多个分布式攻击源时，才进一步判断为DDoS。"},{"anchor":"y2024q49--point-0","title":"相关内容","aliases":[],"text":"攻击主要破坏信息系统的可用性。"},{"anchor":"y2024q49--point-1","title":"相关内容","aliases":[],"text":"流量清洗、限速、扩容、访问控制和异常检测可共同缓解。"},{"anchor":"y2024q49--point-2","title":"相关内容","aliases":[],"text":"IDS用于检测可疑活动，本身不是攻击类型。"},{"anchor":"y2024q49--boundary","title":"易错边界","text":"服务不可用也可能由故障或突发合法流量造成，需结合日志、流量来源和行为模式判断。"},{"anchor":"y2024q49--worked-0","title":"真题怎么判断 · 2024年第49题","text":"2024 第49题 大量连接请求让服务器无法正常提供服务，识别攻击类型。 题设的直接后果是合法用户无法得到服务，受损属性是可用性。 通过耗尽连接、带宽或处理资源造成拒绝服务，对应DoS。 只有题目进一步说明攻击流量来自多个分布式来源时，才有依据明确写DDoS；单凭大量请求不能推出分布式。 看见流量很多就直接判DDoS；或把不可用错当数据泄露。 换一种资源耗尽情境仍先看受损属性：读不到是可用性，内容被改是完整性，秘密被读取是保密性。  原卷完整题干与配套答案已核（v67）；配套答案未认定为官方，未明示分布式时不扩大为DDoS"},{"anchor":"y2024q49--sources","title":"来源与核验记录","text":"题目描述攻击者发送大量请求，使文件服务器无法向正常用户提供服务。 2024 第49题 NIST：分布式拒绝服务的多来源条件"},{"anchor":"y2024q49--demo","title":"守住一台遭遇洪泛的文件服务器","text":"点击流量与防护模块，区分攻击、检测和缓解。"}]},{"id":"y2022q39","kind":"note","chapter":8,"chapterTitle":"信息安全","title":"网络拓扑和分区会影响攻击扩散与可用性","aliases":[],"fields":[{"anchor":"y2022q39--conclusion","title":"核心结论","text":"安全不只取决于软件：连接路径、信任边界和单点故障也会改变风险。"},{"anchor":"y2022q39--point-0","title":"相关内容","aliases":[],"text":"把所有设备放在同一可互访网段，可能扩大横向移动范围。"},{"anchor":"y2022q39--point-1","title":"相关内容","aliases":[],"text":"划分网络区域并按最小权限放行，有助于限制攻击传播，但不能保证绝对隔离。"},{"anchor":"y2022q39--point-2","title":"相关内容","aliases":[],"text":"关键链路和设备冗余可降低部分单点故障风险；仍需检测、切换机制和安全配置。"},{"anchor":"y2022q39--boundary","title":"易错边界","text":"拓扑结构既影响性能，也影响攻击路径和故障影响范围。"},{"anchor":"y2022q39--sources","title":"来源与核验记录","text":"从网络结构与安全的判断与应用整理。 2022 第39题 "},{"anchor":"y2022q39--demo","title":"一台终端出问题，会扩散到哪里","text":"启用分区策略或冗余，再观察攻击和链路故障的影响。"}]},{"id":"y2023q39","kind":"note","chapter":8,"chapterTitle":"信息安全","title":"VPN在公共网络上建立受保护的逻辑专用连接","aliases":[],"fields":[{"anchor":"y2023q39--conclusion","title":"核心结论","text":"VPN通过隧道、加密和认证等机制，在公共网络上建立受保护的逻辑连接，可用于远程接入或站点互联。"},{"anchor":"y2023q39--point-0","title":"远程接入连接授权终端","aliases":["远程接入连接授权终端","先辨连接对象"],"text":"远程接入VPN把授权终端接入组织网络。"},{"anchor":"y2023q39--point-1","title":"站点互联连接网络","aliases":["站点互联连接网络","先辨连接对象"],"text":"站点到站点VPN连接两个或多个局域网。"},{"anchor":"y2023q39--point-2","title":"再核保护范围与条件","aliases":["再核保护范围与条件"],"text":"安全性取决于协议、密钥、身份认证、终端状态和配置。"},{"anchor":"y2023q39--point-3","title":"隧道保护不等于匿名或全部授权","aliases":["隧道保护不等于匿名或全部授权","再核保护范围与条件"],"text":"本节按使用认证和加密的安全VPN理解：保护范围是相应隧道端点之间，出隧道后的访问还受目标服务协议与权限约束。VPN运营方或终端仍可能掌握有关信息，连接VPN不等于匿名保证、免于钓鱼或获得全部资源权限。"},{"anchor":"y2023q39--boundary","title":"易错边界","text":"VPN不会把公共互联网物理变成私有线路，也不会自动阻止终端中毒、钓鱼和越权访问。"},{"anchor":"y2023q39--sources","title":"来源与核验记录","text":"题目判断VPN是否能把公共网络上的连接作为内部网络的安全延伸。 2023 第39题 NIST SP800-77：IPsec VPN的保护范围"},{"anchor":"y2023q39--demo","title":"让校外电脑通过VPN进入校园内网","text":"完成认证、建隧道、访问内网资源和断开四个真实状态。"}]},{"id":"y2020q28","kind":"note","chapter":8,"chapterTitle":"信息安全","title":"病毒具有破坏性，安全仍需多层措施","aliases":["恶意软件","蠕虫","木马","勒索软件","隔离"],"fields":[{"anchor":"y2020q28--conclusion","title":"核心结论","text":"病毒造成数据损坏、资源耗尽或系统异常体现破坏性；防护必须由补丁、最小权限、安全软件、备份和用户判断共同组成。"},{"anchor":"y2020q28--point-0","title":"病毒与其他恶意软件的边界","aliases":["病毒与其他恶意软件的边界"],"text":"病毒还具有寄生性、传染性、潜伏性和触发性等常见特征。"},{"anchor":"y2020q28--point-1","title":"检测、处置与持续防护","aliases":["检测、处置与持续防护"],"text":"安全软件可能漏报、误报或来不及识别新威胁。"},{"anchor":"y2020q28--point-2","title":"检测、处置与持续防护","aliases":["检测、处置与持续防护"],"text":"离线或不可变备份能降低数据破坏和勒索软件损失。"},{"anchor":"y2020q28--point-3","title":"病毒与其他恶意软件的边界","aliases":["病毒与其他恶意软件的边界"],"text":"病毒不仅可能感染可执行程序，也可能依附宏、启动区等；不能凭文件不是.exe就断言安全。"},{"anchor":"y2020q28--point-4","title":"检测、处置与持续防护","aliases":["检测、处置与持续防护"],"text":"防护应落实到操作：可疑邮件链接和附件先独立核实；及时安装官方安全更新；使用安全软件、独立备份与长且唯一的密码，支持时启用多因素认证。"},{"anchor":"y2020q28--point-5","title":"恶意软件与病毒宿主","aliases":["恶意软件与病毒宿主","病毒与其他恶意软件的边界"],"text":"恶意软件是上位概念。病毒把自身代码依附到宿主程序、文档宏或启动区等，在相应条件下执行并感染其他对象；“打开文件后才发现异常”不等于所有病毒都必须由人双击一次才传播。"},{"anchor":"y2020q28--point-6","title":"蠕虫和木马如何区分","aliases":["蠕虫和木马如何区分","病毒与其他恶意软件的边界"],"text":"蠕虫通常是可独立运行、自我复制并通过网络等途径传播的程序，不以感染某个宿主文件作为定义前提；木马则以看似正常或有用的功能诱导运行，暗中执行恶意行为，不以自我复制为定义核心。名称相近不能抹去传播机制区别。"},{"anchor":"y2020q28--point-7","title":"勒索描述目的，不是所有加密","aliases":["勒索描述目的，不是所有加密","病毒与其他恶意软件的边界"],"text":"勒索软件以锁定系统、加密数据等方式索取赎金，也可能伴随窃取与威胁公开数据。同一恶意程序可能结合多种机制；合法加密工具本身不因能加密就变成勒索软件。"},{"anchor":"y2020q28--point-8","title":"潜伏、触发与异常症状","aliases":["潜伏、触发与异常症状","病毒与其他恶意软件的边界"],"text":"潜伏指感染后可能暂不表现明显破坏，触发指满足相应条件后执行某些行为；不是每一种恶意软件都按同一时间表发作。文件变慢、程序异常只是线索，不能单凭一个症状确定病毒种类或宣称已清除。"},{"anchor":"y2020q28--point-9","title":"从告警到处置和恢复","aliases":["从告警到处置和恢复","检测、处置与持续防护"],"text":"发现疑似感染先停止运行可疑内容并限制相关连接，按组织流程报告与处置；用已更新的安全工具扫描，核对告警对象和处置结果，必要时从已知可靠备份恢复并修补原因。删除一个可疑文件、解除隔离或重启，都不能单独证明风险已消除。"},{"anchor":"y2020q28--boundary","title":"易错边界","text":"破坏性不等于立即发作；任何单一产品也不能保证绝对安全。"},{"anchor":"y2020q28--comparison","title":"知识点对照","text":" 类别 主要识别线索 不能直接推出 病毒 感染宿主并传播自身代码 所有恶意软件都属于病毒 蠕虫 可独立自我复制并传播 必须附着.exe文件 木马 伪装有用功能并暗中作恶 一定会自我复制 勒索软件 锁定/加密或以数据胁迫勒索 所有加密程序都是恶意软件"},{"anchor":"y2020q28--sources","title":"来源与核验记录","text":"真题从病毒删除文件、降低效率，以及邮件、补丁、账户和杀毒软件的能力边界考查安全。 2020 第28题 2023 第49题 2024 第39题 2022 第19题 NIST：病毒与宿主 NIST：蠕虫的独立传播 NIST：木马隐藏恶意功能 Microsoft：勒索软件的锁定、加密及数据胁迫 Microsoft：备份与恢复应对勒索"},{"anchor":"y2020q28--demo","title":"先看病毒怎样破坏，再搭多层防线","text":"点击攻击表现和防护措施，观察“特征”与“对策”的对应关系。"}]},{"id":"merged-16","kind":"note","chapter":8,"chapterTitle":"信息安全","title":"防火墙与网络访问控制","aliases":[],"fields":[{"anchor":"merged-16--conclusion","title":"核心结论","text":"防火墙按规则控制经过它的网络流量。判断允许还是阻止，要把同一请求的方向、协议、地址和端口等条件一起代入规则，再考虑未匹配时的默认动作。"},{"anchor":"merged-16--point-0","title":"来源、方向、协议和端口","aliases":["来源、方向、协议和端口","把同一请求的条件一起匹配"],"text":"规则可结合源地址、目标地址、协议、端口和流量方向；具备相应能力的防火墙还可检查连接状态或应用信息。"},{"anchor":"merged-16--point-1","title":"把同一请求的条件一起匹配","aliases":["把同一请求的条件一起匹配"],"text":"一条规则中设置的各项条件通常需要同时满足。例如允许管理网段访问 TCP 3389，不等于允许该网段访问全部端口，也不等于允许任意来源访问 3389。"},{"anchor":"merged-16--point-2","title":"默认动作、冲突与配置核对","aliases":["默认动作、冲突与配置核对"],"text":"未匹配明确规则的流量按默认动作处理。默认拒绝、只开放确有需要的流量，是常用的收紧策略；不能假定任何防火墙都天然采用相同默认值。"},{"anchor":"merged-16--point-3","title":"规则冲突依产品处理","aliases":["规则冲突依产品处理","默认动作、冲突与配置核对"],"text":"多条规则同时相关时，结果取决于产品的处理方式与优先级；教学模型可采用自上而下首条匹配，但应明确这是模型规则。"},{"anchor":"merged-16--point-4","title":"先辨部署与处理能力","aliases":["先辨部署与处理能力"],"text":"防火墙既可部署在网络边界，也可运行在单台主机上；它只能控制经过自身检查路径的流量，记录日志与阻止流量也是两个动作。"},{"anchor":"merged-16--point-5","title":"不能代替其他安全措施","aliases":["不能代替其他安全措施"],"text":"防火墙不是全面防毒工具，允许通过的连接仍可能携带恶意内容；它不能代替更新补丁、身份认证、恶意软件防护、备份和安全意识。"},{"anchor":"merged-16--point-6","title":"包过滤、状态检测与部署位置","aliases":["包过滤、状态检测与部署位置","先辨部署与处理能力"],"text":"包过滤主要依据报文中的地址、协议、端口等字段判断；状态检测还跟踪连接状态，使返回流量等可结合已有连接处理。网络防火墙与主机防火墙说的是部署位置，包过滤与状态检测说的是处理能力，二者不是同一分类维度。"},{"anchor":"merged-16--point-7","title":"配置后同时核对放行和拒绝","aliases":["配置后同时核对放行和拒绝","默认动作、冲突与配置核对"],"text":"实际配置先明确受保护主机和应用需要，再限定方向、协议、地址与端口，保存后核对允许与拒绝两类请求及日志。需要某应用联网时优先按需配置，而不是整体关闭防护；教学演示的首条匹配顺序不能搬成所有产品的优先级。"},{"anchor":"merged-16--boundary","title":"易错边界","text":"下表假设目标是同一台服务器、规则只允许来自 10.20.0.0/16 的入站 TCP 3389，其余默认拒绝。不要仅凭“内网地址”或“端口已开放”就判定一次访问一定获准。"},{"anchor":"merged-16--comparison","title":"知识点对照","text":" 同一服务器收到的请求 是否满足允许规则 结果 10.20.8.16 → TCP 3389（入站） 来源、协议、端口和方向均满足 允许 203.0.113.27 → TCP 3389（入站） 来源不在管理网段 默认拒绝 10.20.8.16 → TCP 80（入站） 端口不符 默认拒绝 10.20.8.16 → UDP 3389（入站） 协议不符 默认拒绝"},{"anchor":"merged-16--sources","title":"来源与核验记录","text":"三道题从边界防护、内网保护和访问控制角度考查防火墙。 2020 第40题 2025 第16题 2026 第17题 2022 第29题 2021 第39题 NIST SP 800-41 Rev.1：防火墙与策略指南 NIST SP 800-41 Rev.1 正文：规则、状态检查与默认拒绝"},{"anchor":"merged-16--demo","title":"同一份请求穿过规则：来源、方向、端口一起判断","text":"修改请求、添加规则或真正拖动规则次序，再发送请求观察首条命中。"}]},{"id":"syllabus-windows-security","kind":"note","chapter":8,"chapterTitle":"信息安全","title":"Windows 10安全：扫描、流量控制、权限提升与恢复分工","aliases":["Windows安全中心","Windows Defender","Microsoft Defender Antivirus","UAC","用户账户控制","权限提升","Windows Update"],"fields":[{"anchor":"syllabus-windows-security--conclusion","title":"核心结论","text":"Windows安全中心汇总状态；Defender防病毒检查恶意内容，防火墙控制网络通信，UAC控制权限提升。更新、资源权限与独立备份分别降低其他风险，不能互相替代。"},{"anchor":"syllabus-windows-security--point-0","title":"Windows安全中心是入口集合","aliases":["Windows安全中心是入口集合","识别安全入口和保护对象"],"text":"Windows 10可从开始菜单搜索“Windows安全中心”，或设置→更新和安全→Windows安全中心进入。它是状态与功能入口的集合，不等于其中每一项都由同一个杀毒功能完成；小版本、第三方安全软件和组织策略可能改变显示。"},{"anchor":"syllabus-windows-security--point-1","title":"Defender扫描与结果核对","aliases":["Defender扫描与结果核对","识别安全入口和保护对象"],"text":"要检查恶意软件，进入“病毒和威胁防护”，先核对提供保护的产品、保护状态与安全情报更新，再运行快速扫描或按需要使用扫描选项。Microsoft Defender Antivirus（旧称Windows Defender防病毒）承担反恶意软件职责；一次未检出不能证明任何文件都安全。"},{"anchor":"syllabus-windows-security--point-2","title":"隔离、允许与恢复不同","aliases":["隔离、允许与恢复不同","识别安全入口和保护对象"],"text":"在保护历史记录中核对告警对象、时间和已采取的动作。隔离用于限制可疑项目继续运行，不等于允许它，也不等于原业务数据一定已恢复；不要为消除提示而随意允许或还原未经核实的项目。"},{"anchor":"syllabus-windows-security--point-3","title":"本机防火墙与网络配置","aliases":["本机防火墙与网络配置","识别安全入口和保护对象"],"text":"进入“防火墙和网络保护”，先认清当前域、专用或公用网络配置，再检查保护状态和确有需要的应用放行范围。Windows防火墙通常阻止未获允许的入站、允许未被规则阻止的出站；组织策略可改变配置，明确阻止与允许冲突时通常阻止优先，不能套用本章演示的首条匹配。"},{"anchor":"syllabus-windows-security--point-4","title":"标准用户与管理员的UAC提示","aliases":["标准用户与管理员的UAC提示","权限请求、确认与实际结果"],"text":"UAC处理需要提升权限的操作。在启用UAC、采用常见默认策略时，管理员账户通常确认提升，标准账户需要有效管理员凭据；拒绝或取消则不授予这次提升。提示策略可能不同，不是所有按钮或每次文件编辑都会弹出UAC。"},{"anchor":"syllabus-windows-security--point-5","title":"允许提升不等于程序安全","aliases":["允许提升不等于程序安全","权限请求、确认与实际结果"],"text":"出现提升提示，先核对程序、发布者、来源及是否由自己发起，再决定允许或拒绝。允许只是让该程序继续执行相应管理任务，不是杀毒结果或真实性保证；标准用户借助管理员凭据完成一次任务，也不会自动变成管理员账户。"},{"anchor":"syllabus-windows-security--point-6","title":"更新入口和Windows 10支持条件","aliases":["更新入口和Windows 10支持条件","更新、文件保护与恢复"],"text":"Windows 10的设置→更新和安全→Windows更新可检查适用更新，按提示完成安装并在需要时重启。更新用于修补漏洞等问题，不保证永不受攻击；常规Windows 10支持已于2025年10月14日结束，之后能否获得新安全更新须核对具体版本和扩展支持条件，不能把考试菜单当作当前持续支持承诺。"},{"anchor":"syllabus-windows-security--point-7","title":"权限与EFS关联","aliases":["权限与EFS关联","更新、文件保护与恢复"],"text":"账户身份、NTFS访问权限与EFS加密密钥分层判断：有管理员身份不等于自动能解密任何文件，隐藏/只读属性也不能替代安全权限。具体设置与版本条件沿用第2章文件权限及EFS入口，本节不另建一套规则。"},{"anchor":"syllabus-windows-security--point-8","title":"备份不等于系统还原","aliases":["备份不等于系统还原","更新、文件保护与恢复"],"text":"独立备份用于受损后的恢复，应检查是否能读取所需版本；备份本身不阻止入侵。系统还原主要回退系统状态，不是个人文件备份；隔离或清除恶意程序也不保证被破坏的文档自动回来。"},{"anchor":"syllabus-windows-security--point-9","title":"从操作对象判断是否需要提升","aliases":["从操作对象判断是否需要提升","权限请求、确认与实际结果"],"text":"完整判断例：普通编辑自己的笔记通常使用当前用户权限；调整受保护的系统时间可能要求提升。取消提示则系统时间保持，确认或凭据验证成功后才可继续该管理任务；任务完成仍须核对结果，并继续保留反病毒、更新和文件权限保护。"},{"anchor":"syllabus-windows-security--boundary","title":"易错边界","text":"入口以Windows 10桌面版为考试基线，UAC和防火墙行为受策略影响；原生Windows 10未实测。"},{"anchor":"syllabus-windows-security--demo-limits","title":"本演示的范围与限制","text":"网页只演示有限的权限请求与设置提交，不修改电脑、不接收真实密码，也不模拟完整安全中心。"},{"anchor":"syllabus-windows-security--comparison","title":"知识点对照","text":" 对象或任务 主要机制 不能替代 可疑程序/文件 反恶意软件扫描、隔离 不能保证无漏报，也不保证恢复被破坏文件 网络连接 主机防火墙规则 不是给用户授予文件权限 程序请求管理权限 UAC确认或凭据 不是鉴定程序是否恶意 已知系统缺陷 适用安全更新 不是所有攻击的免疫保证 受损后的资料恢复 可靠的独立备份 不能代替日常防护"},{"anchor":"syllabus-windows-security--sources","title":"来源与核验记录","text":"面对可疑文件、联网请求、管理员提示和系统漏洞，先判断对象再选机制。  Microsoft：Windows10安全中心、扫描与保护入口 Microsoft：UAC提示、标准账户与管理员批准模式 Microsoft：Defender防病毒与Windows安全界面 Microsoft：Windows防火墙规则及冲突优先级 Microsoft：网络配置与防火墙入口 Microsoft：Windows更新及支持条件"},{"anchor":"syllabus-windows-security--demo","title":"同一个系统设置：先取得权限，再确认修改","text":"比较普通编辑与系统时间更改；取消提升或取消草稿都不会提交设置。"}]},{"id":"y2020q20","kind":"note","chapter":8,"chapterTitle":"信息安全","title":"网络行为要尊重权限、署名与责任边界","aliases":[],"fields":[{"anchor":"y2020q20--conclusion","title":"核心结论","text":"使用网络与信息资源应遵守访问权限、许可条款和法定使用限制，诚实标明来源并对传播后果负责；改写措辞也不能抹去他人贡献。"},{"anchor":"y2020q20--point-0","title":"技术访问与法律授权","aliases":["技术访问与法律授权","权限、伦理与法律分别判断"],"text":"访问控制限制账户对资源的读取、修改等操作；技术权限与传播、复制作品所需的法律授权不是同一层。"},{"anchor":"y2020q20--point-1","title":"权限、伦理与法律分别判断","aliases":["权限、伦理与法律分别判断"],"text":"引用应使来源和贡献边界可追溯。"},{"anchor":"y2020q20--point-2","title":"负责任地获取和传播信息","aliases":["负责任地获取和传播信息"],"text":"传播前要核验事实、隐私、授权与潜在伤害。"},{"anchor":"y2020q20--point-3","title":"适当引用的条件","aliases":["适当引用的条件","作品、软件与个人信息"],"text":"账号、文件和数据的访问授权，与作品使用的著作权规则应分别判断。为介绍、评论作品或说明问题而适当引用已发表作品，符合著作权法第二十四条条件时可免许可；仍须指明作者及作品，不妨碍作品正常使用，不得不合理地损害权利人的合法权益。署名并不等于可无限复制。"},{"anchor":"y2020q20--point-4","title":"伦理、法律和场景规范","aliases":["伦理、法律和场景规范","权限、伦理与法律分别判断"],"text":"伦理原则强调诚实、尊重与避免伤害，法律规定权利义务和责任，学校、平台或单位规范还可能提出具体要求。应分别判断，不能把“建议署名”当作已经取得复制或传播许可，也不能把每次违反礼仪都直接认定为违法。"},{"anchor":"y2020q20--point-5","title":"个人信息处理的目的和基础","aliases":["个人信息处理的目的和基础","作品、软件与个人信息"],"text":"可识别个人的信息不只在收集时需要保护，存储、使用、分享也有边界。在个人信息保护法适用范围内，应有明确合理目的并遵守最小必要原则；同意、合同必要、法定义务等是不同法定处理基础，不能概括成“任何处理都只能靠同意”。个人信息与隐私有交叉，已公开的信息也不等于可无限利用。"},{"anchor":"y2020q20--point-6","title":"软件许可不是全部著作权","aliases":["软件许可不是全部著作权","作品、软件与个人信息"],"text":"购买或下载软件通常取得约定范围内的使用许可，不因此取得软件全部著作权。安装、自用备份与对外分发要分别查许可或法定例外；网上可下载、标了作者或称为免费，都不自动表示可以任意复制传播。"},{"anchor":"y2020q20--point-7","title":"虚假信息识别与职业自律","aliases":["虚假信息识别与职业自律","负责任地获取和传播信息"],"text":"判断消息真假先查原始出处、发布时间、上下文和可交叉核对的证据，区分事实、观点与猜测。职业自律还要求按职责使用数据、保守应保密的信息并纠正错误；未核实的内容不要靠反复转发增加“可信度”，具体法律责任另看行为与适用规范。"},{"anchor":"y2020q20--boundary","title":"易错边界","text":"“技术上能做到”不等于“有权做”；没有逐字复制也不自动排除抄袭。"},{"anchor":"y2020q20--sources","title":"来源与核验记录","text":"真题从未授权访问和改写他人成果考查信息伦理。 2020 第20题 2024 第19题 著作权法第二十四条：使用限制 中国人大网全文（网信办转载）：个人信息保护法第4、6、13、27、72条 司法部现行法规库：计算机软件保护条例2013修订"},{"anchor":"y2020q20--demo","title":"先问“有没有授权”","text":"点击网络行为，观察权限、目的和影响三个判断维度。"}]},{"id":"y2026q30","kind":"note","chapter":8,"chapterTitle":"信息安全","title":"使用AI生成内容要核验、披露并尊重权利","aliases":[],"fields":[{"anchor":"y2026q30--conclusion","title":"核心结论","text":"应核验事实、尊重著作权与隐私，并在公开传播或特定场景中按适用规则标识、说明AI生成合成属性。"},{"anchor":"y2026q30--point-0","title":"先核验内容与权利","aliases":["先核验内容与权利"],"text":"不能把AI输出当成天然真实或权威来源。"},{"anchor":"y2026q30--point-1","title":"先核验内容与权利","aliases":["先核验内容与权利"],"text":"引用他人资料和用于学术、创作时应按规范披露来源与AI参与程度。"},{"anchor":"y2026q30--point-2","title":"再判断标识对象和传播场景","aliases":["再判断标识对象和传播场景"],"text":"我国现行规则区分显式标识与隐式标识，并规定服务提供者、传播平台和用户的相应义务。"},{"anchor":"y2026q30--point-3","title":"显式和隐式标识","aliases":["显式和隐式标识","再判断标识对象和传播场景"],"text":"显式标识可被人明显感知，例如文字、声音或画面提示；隐式标识以技术方式写入文件数据。看不到水印不表示没有标识；标识说明生成属性，也不证明内容真实或已经获得他人权利许可。"},{"anchor":"y2026q30--point-4","title":"用户公开传播的声明义务","aliases":["用户公开传播的声明义务","再判断标识对象和传播场景"],"text":"按《人工智能生成合成内容标识办法》，用户通过网络信息内容传播服务发布生成合成内容时，应主动声明并使用平台提供的标识功能，不得恶意删除、篡改、伪造或隐匿标识。私人自用、公开传播及特定行业要求应分别判断，不能套成同一形式。"},{"anchor":"y2026q30--point-5","title":"输入资料和输出核验","aliases":["输入资料和输出核验","先核验内容与权利"],"text":"使用AI辅助学习时先确定资料是否可提供，避免把未获授权的个人信息或保密材料直接上传；对生成的事实、引文和来源逐项核验，再按场景说明AI参与。人工确认与标识都不能替代对著作权、隐私和传播后果的责任。"},{"anchor":"y2026q30--boundary","title":"易错边界","text":"不是所有私人使用都要求相同形式的标识；应结合是否传播、平台规则、内容类型和具体法律规范判断。"},{"anchor":"y2026q30--sources","title":"来源与核验记录","text":"题目要求判断使用生成式人工智能时哪些做法合规。 2026 第30题 网信办：人工智能生成合成内容标识办法第3、10条 网信办：标识办法适用范围及规则解读"},{"anchor":"y2026q30--demo","title":"发布AI内容前过三道门","text":"点击检查项，形成公开传播前的操作顺序。"}]}];
